    h,w=len(grid),len(grid[0])
    bg=max({v for row in grid for v in row},key=lambda v:sum(row.count(v) for row in grid))
    # Extend diagonals made by the dominant non-background marker color; other colors are endpoints/noise.
    colors={v for row in grid for v in row if v!=bg}
    counts={v:sum(row.count(v) for row in grid) for v in colors}
    col=max(colors,key=counts.get)
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==col}
    for dr,dc in ((1,1),(1,-1)):
        for r,c in pts:
            if (r+dr,c+dc) in pts:
                rr,cc=r,c
                while 0<=rr<h and 0<=cc<w:
                    if out[rr][cc]==bg: out[rr][cc]=col
                    rr-=dr;cc-=dc
                rr,cc=r+dr,c+dc
                while 0<=rr<h and 0<=cc<w:
                    if out[rr][cc]==bg: out[rr][cc]=col
                    rr+=dr;cc+=dc
    return out
